// Google's favicon service - reliable, returns each brand's logo mark.
const lc = (domain: string) =>
  `https://www.google.com/s2/favicons?domain=${domain}&sz=128`;

type Seed = Omit<Tool, "listingCost"> & { listingCost?: string };
const T = (s: Seed): Tool => {
  const shot = SCREENSHOTS[s.slug];
  return {
    listingCost: "Free · promoted from $49",
    ...s,
    // Prepend the captured homepage screenshot as the lead gallery image.
    // Always an explicit array so a re-seed clears stale paths for tools
    // whose screenshot was removed.
    images: shot ? [shot, ...(s.images ?? [])] : (s.images ?? []),
  };
};

